select sc.*, T.count as click_count from ( SELECT count(*) as count, service_id FROM wx_click_service_log
and open_id = #{openid}
GROUP BY service_id ) T left join service_config sc on T.service_id = sc.id and sc.is_deactivated = 0 ORDER BY click_count DESC

select sc.*, T.latest_click_time as latest_click_time from ( SELECT service_id, MAX(create_time) AS latest_click_time FROM wx_click_service_log where service_id is not null
and open_id = #{openid}
AND service_id IN ( SELECT min_sc.uuid FROM ( SELECT uuid, MIN(id) AS min_id FROM service_config WHERE is_deactivated = 0 GROUP BY uuid ) min_sc ) GROUP BY service_id ORDER BY latest_click_time DESC LIMIT 5 ) T LEFT JOIN ( SELECT all_sc.* FROM service_config all_sc JOIN ( SELECT uuid, MIN(id) AS min_id FROM service_config WHERE is_deactivated = 0 GROUP BY uuid ) min_sc ON all_sc.uuid = min_sc.uuid AND all_sc.id = min_sc.min_id WHERE all_sc.is_deactivated = 0 ) sc ON T.service_id = sc.uuid;
